@Component("wishlist-handler")
@ProcessingGroup("wishlist-processing-group")
public class WishlistEventHandler {
	
	// core constructor
	WishlistEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateWishlistEvent
     */
    @EventHandler
    public void handle( CreateWishlistEvent event) {
        entityManager.persist(new Wishlist(event.getWishlistId(), event.getName(), event.getAsPublic(), event.getCreatedAt(), event.getCustomer(), event.getItems()));
    }

    /*
     * @param	event UpdateWishlistEvent
     */
    @EventHandler
    public Wishlist handle( UpdateWishlistEvent event) {
    	entityManager.merge(new Wishlist(event.getWishlistId(), event.getName(), event.getAsPublic(), event.getCreatedAt(), event.getCustomer(), event.getItems()));
    }
    
    /*
     * @param	event DeleteWishlistEvent
     */
    @EventHandler
    public void on( DeleteWishlistEvent event) {
    	Wishlist entity = new Wishlist();
   
    	// ------------------------------------------
    	// apply the WishlistId
    	// ------------------------------------------
    	entity.setWishlistId( event.getWishlistId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final WishlistRepository wishlistEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(WishlistEventHandler.class.getName());

}
